INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63059691', 63059691, 'analyze_legacy', 'Mahkamah Agung', 'central', 'PENGADILAN AGAMA ARGAMAKMUR01', 'Satpam', 'Jasa Lainnya', 'E-Purchasing', 'Bengkulu, Bengkulu Utara (Kab.)', 132717000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '3 Orang', 'Ruang lingkup kegiatan ini adalah tersedianya tenaga keamanan/SATPAM untuk Kantor Pengadilan Agama Arga Makmur selama 1 (satu) Tahun Anggaran.', 'a. Syarat Perusahaan 1. Koordinator Lapangan minimal bersertifikat Gada Pratama 2. Mengedepankan “Service Excellent Culture” 3. Memiliki Surat Izin Usaha dari instansi yang berwenang dan masih berlaku pada bidang jasa Keamanan. 4. Memiliki Izin jasa penyelenggara Outsourcing 5. Memiliki Sertifikat kepesertaan Jaminan Sosial Tenaga Kerja/BPJS ketenagakerjaan yang masih berlaku 6. Perusahaan yang bersangkutan dan manajemen tidak dalam pengawasan pengadilan, tidak pailit, kegiatan usahanya tidak sedang dihentikan dan/atau direksi yang bertindak untuk dan atas nama perusahaan atau peserta perorangan tidak sedang dalam menjalani sanksi pidana. 7. Salah satu dan/atau semua pengurus dan badan usahanya atau perseorangan tidak masuk dalam daftar hitam. 8. Memiliki NPWP dan telah memenuhi kewajiban perpajakan tahun pajak terakhir (SPT Tahunan). b. Persyaratan Tenaga Satpam 1. Pria/Wanita usia minimal 20 tahun dan maksimal 40 tahun 2. Pendidikan sekurang-kurangnya lulusan SLTA/Sederajat 3. Tinggi badan minimal : Wanita 155 cm dan Pria 160 cm 4. Berbadan sehat yang dibuktikan dengan surat keterangan dokter dan tidak mempunyai riwayat penyakit yang akan mengganggu pelaksanaan tugas 5. Diutamakan sudah berpengalaman sebagai petugas keamanan / security minimal 2 tahun yang dibuktikan dengan surat keterangan dari pengguna jasa (bermeterai Rp. 10.000) 6. Seluruh Personil Tenaga Keamanan memiliki sertifikat pelatihan security / keamanan bersertifikat Gada Madya dan Gada pratama yang dikeluarkan oleh instansi resmi / kepolisian 7. Bersikap sopan, jujur, dapat bekerjasama. 8. Mampu berkomunikasi dan mempunyai semangat tinggi 9. Siap bekerja shift dan mentaati segala aturan yang ditetapkan oleh instansi pengguna jasa layanan keamanan 10. Berkelakuan baik yang dibuktikan dengan SKCK dari kepolisian 11. Surat Keterangan Bebas Narkoba dari klinik/BNN c. Kewajiban Calon Penyedia Barang/Jasa terhadap Tenaga Satpam 1. Penyedia barang/jasa memberikan hak-hak kepada tenaga kerja sesuai ketentuan UU Ketenagakerjaan yang berlaku. 2. Tenaga Keamanan harus didaftarkan sebagai peserta BPJS Kesehatan dan Ketenagakerjaan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 532079);
