INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63035573', 63035573, 'analyze_legacy', 'Kota Balikpapan', 'kabkota', 'UPTD-RUMAH SAKIT UMUM DAERAH', 'Pemeliharaan Kendaraan Dinas/Operasional', 'Jasa Lainnya', 'Penunjukan Langsung', 'Kalimantan Timur, Balikpapan (Kota)', 50000000, 'January 2026', 'BLUD', 1, 1, '1 Paket', 'Pemeliharaan kendaraan dinas/operasional meliputi kegiatan perawatan rutin dan perbaikan kendaraan agar tetap layak jalan, aman, dan siap digunakan untuk mendukung pelayanan dan penunjang pelayanan RSUD Beriman Balikpapan. Pekerjaan ini mencakup servis berkala, pemeriksaan dan penggantian suku cadang, perbaikan mesin, sistem kelistrikan, rem, ban, serta pengecekan kelengkapan kendaraan. Selain itu, dilakukan penggantian oli dan pelumas, penyetelan komponen, serta perbaikan lain yang diperlukan guna menjamin kelancaran operasional, keselamatan pengguna, dan keberlangsungan pelayanan dan penunjang pelayanan RSUD Beriman Balikpapan', 'Pemeliharaan kendaraan dinas/operasional meliputi perawatan dan perbaikan untuk memastikan kendaraan dalam kondisi layak jalan, aman, dan optimal digunakan. Spesifikasi pekerjaan mencakup pemeriksaan dan servis berkala mesin, penggantian oli dan filter, perawatan sistem bahan bakar, pendingin, dan pelumasan, serta pengecekan dan perbaikan sistem rem, kemudi, suspensi, dan ban. Selain itu, dilakukan pemeriksaan dan perbaikan sistem kelistrikan, aki, lampu, serta kelengkapan kendaraan lainnya. Seluruh pekerjaan menggunakan suku cadang dan bahan sesuai standar pabrikan, dikerjakan oleh teknisi berkompeten, dan disertai laporan hasil pemeliharaan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 534638);
