INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63061704', 63061704, 'analyze_legacy', 'Kementerian Energi Dan Sumber Daya Mineral', 'central', 'SEKRETARIAT JENDERAL KEMENTERIAN ENERGI DAN SUMBER DAYA MINERAL', 'pembuatan Video Grafis', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 200000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Publikasi di era digital mengalami banyak perubahan pendekatan, sebelumnya materi publikasi pemerintah lebih banyak menggunakan narasi yang panjang dan tidak menarik. Tapi saat ini pengemasan materi publikasi lebih menarik dengan Infografis dan Videografis. Pemerintah sebagai regulator yang mengatur segala kepentingan masyarakat perlu untuk membuat skema publikasi yang menarik bagi masyarakat. Tujuan pentingnya publikasi di era moderndari kegiatan publikasi secara luas adalah untuk menghindari asimetris informasi yang dapat menghambat pembangunan di Indonesia.', '1. Mengumpulkan bahan publikasi dari unit-unit Kementerian ESDM 2. Merangkum informasi yang akan disajikan 3. Pembuatan videografis dan caption 4. Publikasi untuk disajikan pada Pimpinan KESDM 5. Pembuatan laporan akhir pekerjaan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 536645);
